#include <stdio.h>

int main(void) {
    int n, i;
    scanf("%d", &n);
    int is_prime = 1;
    if (n < 2) {
        is_prime = 0;
    }
    for (i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            is_prime = 0;
            break;
        }
    }
    printf("%s\n", is_prime ? "Prime" : "Not Prime");
    return 0;
}

