#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int count = 0;
    int candidate = 2;
    while (count < n) {
        int is_prime = 1;
        int i;
        for (i = 2; i * i <= candidate; i++) {
            if (candidate % i == 0) {
                is_prime = 0;
                break;
            }
        }
        if (is_prime) {
            printf("%d\n", candidate);
            count++;
        }
        candidate++;
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int pin, attempt;
    int tries = 0;
    int unlocked = 0;
    scanf("%d", &pin);
    do {
        scanf("%d", &attempt);
        tries++;
        if (attempt == pin) {
            unlocked = 1;
            break;
        }
    } while (tries < 3);
    printf("%s\n", unlocked ? "Unlocked" : "Locked");
    return 0;
}

