            printf("*");
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    long long n;
    scanf("%lld", &n);
    long long factor = 2;
    while (factor * factor <= n) {
        while (n % factor == 0) {
            printf("%lld\n", factor);
            n /= factor;
        }
        factor++;
    }
    if (n > 1) {
        printf("%lld\n", n);
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    long long low, high;
    scanf("%lld %lld", &low, &high);
    long long i;
    for (i = low; i <= high; i++) {
        long long temp = i;
        int ndigits = 0;
        if (temp == 0) ndigits = 1;
        while (temp != 0) {
            ndigits++;
            temp /= 10;
        }
        long long sum = 0;
        temp = i;
        while (temp != 0) {
            int digit = (int)(temp % 10);
            long long p = 1;
            int k;
            for (k = 0; k < ndigits; k++) {
                p *= digit;
            }
            sum += p;
            temp /= 10;
        }
        if (sum == i) {
            printf("%lld\n", i);
        }
    }
    return 0;
}
